// Interpreta la respuesta del agente de IA y arma el correo.
// Si la IA falló o no devolvió JSON válido, se usa una prioridad por reglas para que el aviso igual salga.
const r = $('Webhook LabControl').first().json.body;
const ia = $input.first().json;

let d = {};
try {
  const texto = String(ia.output ?? ia.text ?? '').replace(/```json|```/g, '').trim();
  const inicio = texto.indexOf('{'), fin = texto.lastIndexOf('}');
  d = JSON.parse(texto.slice(inicio, fin + 1));
} catch (e) { d = {}; }

const reglas = { PERDIDO: 'ALTA', DANADO: 'ALTA', FALLA: 'MEDIA', AGOTADO: 'MEDIA', OTRO: 'BAJA' };
let prioridad = String(d.prioridad || '').toUpperCase().trim();
const porIa = ['ALTA', 'MEDIA', 'BAJA'].includes(prioridad);
if (!porIa) prioridad = reglas[r.tipo] || 'MEDIA';

const corta = (s, n) => { s = String(s ?? '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const asunto = corta(d.asunto || `[${prioridad}] Novedad en ${r.equipo.placa} · ${r.tipoTexto} · ${r.sede.nombre}`, 150);
const resumen = corta(d.resumen || `${r.reportadoPor} reportó "${r.tipoTexto}" en ${r.equipo.placa} (${r.equipo.nombre}), laboratorio de ${r.equipo.laboratorio}, ${r.sede.nombre}.`, 1000);
const accion = corta(d.accionSugerida || 'Revisar el equipo y definir si requiere reparación, reposición o baja.', 600);
const color = { ALTA: '#B91C1C', MEDIA: '#B45309', BAJA: '#047857' }[prioridad];

const fila = (k, v) => `<tr><td style="padding:6px 10px;color:#64748b;white-space:nowrap">${k}</td><td style="padding:6px 10px;color:#0f172a"><b>${esc(v)}</b></td></tr>`;
const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden">
  <div style="background:#8F141B;color:#fff;padding:16px 20px">
    <div style="font-size:12px;letter-spacing:1px;opacity:.85">USCO LABCONTROL · ${esc(r.sede.nombre).toUpperCase()}</div>
    <div style="font-size:18px;font-weight:bold;margin-top:4px">Novedad en ${esc(r.equipo.placa)} · ${esc(r.tipoTexto)}</div>
  </div>
  <div style="padding:20px">
    <span style="display:inline-block;background:${color};color:#fff;font-weight:bold;border-radius:999px;padding:4px 12px;font-size:13px">Prioridad ${prioridad}${porIa ? '' : ' (por reglas)'}</span>
    <p style="color:#0f172a;line-height:1.5">${esc(resumen)}</p>
    <p style="margin:0;color:#64748b;font-size:13px">Acción sugerida</p>
    <p style="color:#0f172a;line-height:1.5;margin-top:4px">${esc(accion)}</p>
    <table style="border-collapse:collapse;font-size:14px;margin-top:8px;background:#f8fafc;border-radius:8px">
      ${fila('Equipo', `${r.equipo.placa} · ${r.equipo.nombre}`)}
      ${fila('Laboratorio', `${r.equipo.laboratorio}${r.equipo.ubicacion ? ' · ' + r.equipo.ubicacion : ''}`)}
      ${fila('Reportó', r.reportadoPor)}
      ${fila('Fecha', r.fechaTexto)}
      ${fila('Mantenimiento', r.enviadoAMantenimiento ? 'Sí, se retiró del préstamo' : 'No')}
    </table>
    <p style="margin:16px 0 4px;color:#64748b;font-size:13px">Descripción del auxiliar</p>
    <blockquote style="margin:0;border-left:4px solid #DFD4A6;padding:8px 12px;color:#334155">${esc(r.descripcion)}</blockquote>
    <p style="margin-top:20px"><a href="${esc(r.enlace)}" style="background:#8F141B;color:#fff;text-decoration:none;padding:10px 16px;border-radius:8px;font-weight:bold">Abrir inventario</a></p>
    ${d.justificacion ? `<p style="font-size:12px;color:#64748b">Criterio de la IA: ${esc(corta(d.justificacion, 300))}</p>` : ''}
  </div>
</div>`;

return [{ json: { destinatario: r.destinatario, asunto, html, prioridad, resumen, accionSugerida: accion, priorizadoPorIa: porIa } }];
